// Fichier généré depuis le jeu Ottho Quest (public/sprites, public/icons, public/scenes) : ne pas le modifier à la main.

/** Une image du jeu et sa taille en pixels. */
export type Picture = { src: string; w: number; h: number }

/** Un personnage du jeu : son image, sa taille, le milieu de ses pieds. */
export type Sprite = Picture & { foot: number }

